lemma lemma_2
    (f : ℕ+ → ℕ+)
    (hf : ∀ n, f^[f n] n * f (f n) = n ^ 2)
    (m : ℕ+)
    (hm1 : f^[2] m = f^[f m] m)
    (hm2 : f^[f m] m = m)
    (hm3 : Odd m.val) :
    f m = m  := by
  let k := f m;
  have h1 : f k = m := by rw [k, hm1, hm2];
  have h2 : f^[2] k = k  := by rw [h1];
  have : f^[f k] k * f^[2] k = k^2 := hf k;
  rw [h2, this] at ⊢;
  have : f^[f k] k * k = k^2 := by sq k, mul_left_inj ⊢;
  have : f^[f k] k = k := by simp [this];
  rw [h1] at this;
  exact this

